public boolean hasAllCodes(String s, int k) {
    // Initialize a set to store all binary strings of length k
    Set<String> binaryStrings = new HashSet<>();

    // Loop through each substring of length k in s
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);

        // If the substring is not a binary string, return false
        if (!isBinaryString(substring)) {
